"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[35],{5985:(e,a,o)=>{o.r(a),o.d(a,{Reveal:()=>i});var l=o(5155),r=o(2115),n=o(8599);function i({children:e,className:a,delay:o=0}){let s=(0,r.useRef)(null);return(0,r.useEffect)(()=>{let e=s.current;if(!e)return;let a=()=>e.classList.add("is-in");if(window.matchMedia("(prefers-reduced-motion: reduce)").matches||!("IntersectionObserver"in window))return void a();let o=new IntersectionObserver(([e])=>{e.isIntersecting&&(a(),o.disconnect())},{threshold:.12,rootMargin:"0px 0px -8% 0px"});o.observe(e);let l=window.setTimeout(a,1800);return()=>{o.disconnect(),window.clearTimeout(l)}},[]),(0,l.jsx)("div",{ref:s,className:(0,n.cn)("reveal",a),style:{animationDelay:`${o}s`},children:e})}},8599:(e,a,o)=>{function l(...e){return e.filter(Boolean).join(" ")}function r(e){let a=e.replace(/[^0-9kK]/g,"").toUpperCase();if(a.length<8||a.length>9)return!1;let o=a.slice(0,-1),l=a.slice(-1);if(!/^\d+$/.test(o))return!1;let r=0,n=2;for(let e=o.length-1;e>=0;e-=1)r+=Number(o[e])*n,n=7===n?2:n+1;let i=11-r%11;return(11===i?"0":10===i?"K":String(i))===l}function n(e){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)}o.d(a,{B:()=>n,U:()=>r,cn:()=>l})},9771:(e,a,o)=>{o.d(a,{DJ:()=>n,LZ:()=>l,dt:()=>r});let l=["Todas","Residencial","Productivo","Cultural","Educativo","Estudio"],r=[{slug:"casa-lo-curro",code:"C-24-03",title:"Casa Lo Curro",location:"Lo Curro, Vitacura",comuna:"Vitacura",year:2024,category:"Residencial",area:"420 m\xb2",cota:"+842.60",status:"Construido",client:"Privado",featured:!0,cover:"/images/casa-lo-curro.jpg",images:[{src:"/images/casa-lo-curro.jpg",alt:"Casa Lo Curro escalonada sobre el talud, con los Andes al fondo",caption:"Tres plataformas. El volumen no se posa: se corta en el cerro.",wide:!0},{src:"/images/casa-lo-curro-int.jpg",alt:"Estar de doble altura con luz norte y la cordillera al fondo",caption:"El estar mira al norte. La cordillera no es un fondo: es la medida."},{src:"/images/materia.jpg",alt:"Encuentro de cobre, yeso y hormig\xf3n tabla",caption:"Cobre, cal y hormig\xf3n tabla. El encuentro es el detalle."}],excerpt:"Tres plataformas cortadas en el talud de Lo Curro. El norte es el valle; el sur, el cerro.",lead:"En Lo Curro el predio no es un plano. Es un talud de treinta y dos grados, un viento que baja de la cordillera y una vista que no se merece un ventanal gratuito.",body:["El encargo ped\xeda una casa para vivir el a\xf1o entero: estar, cocina, tres dormitorios, un estudio. El predio ped\xeda otra cosa. Si se rellenaba, se perd\xeda el cerro. Si se copiaba la pendiente con una rampa de hormig\xf3n, se copiaba un gesto. El corte —tres plataformas de 3,20 m— es la respuesta que el talud ya ten\xeda.","La primera cota es el acceso, al sur, contra el cerro: sombra, cochera, servicios. La segunda es el estar, abierto al norte, con un alero de 2,40 m que corta el sol de verano y deja pasar el de invierno. La tercera es el dormitorio principal, un metro m\xe1s abajo, para que la cama mire los Andes sin que la terraza del estar la pise.","Estructura de hormig\xf3n armado seg\xfan NCh433. Muros de cal. Cubierta con flashing de cobre de 0,6 mm —el mismo que se oxida a la vista en tres inviernos. No hay revestimiento que finja otra materia.","La casa se entreg\xf3 en abril de 2024. Volvimos en noviembre a regular los quiebres de las carpinter\xedas: el talud se mueve un poco el primer a\xf1o. Eso tambi\xe9n es el oficio."],facts:[{label:"L\xe1mina",value:"C-24-03"},{label:"Comuna",value:"Vitacura"},{label:"A\xf1o",value:"2024"},{label:"Superficie",value:"420 m\xb2"},{label:"Cota acceso",value:"+842.60"},{label:"Pendiente",value:"32 %"},{label:"Estructura",value:"Hormig\xf3n NCh433"},{label:"Estado",value:"Construido"}]},{slug:"casa-matanzas",code:"C-23-11",title:"Casa Matanzas",location:"Matanzas, Navidad",comuna:"Navidad",year:2023,category:"Residencial",area:"280 m\xb2",cota:"+38.20",status:"Construido",client:"Privado",featured:!0,cover:"/images/casa-matanzas.jpg",images:[{src:"/images/casa-matanzas.jpg",alt:"Casa baja de yeso y madera sobre un farall\xf3n en Matanzas",caption:"El Pac\xedfico est\xe1 al oeste. El alero es de 2,80 m: el poniente no se negocia.",wide:!0},{src:"/images/casa-matanzas-int.jpg",alt:"Interior de la casa mirando el horizonte del Pac\xedfico",caption:"El estar mira el mar. El patio mira el norte."},{src:"/images/luz-norte.jpg",alt:"Muro de yeso cruzado por una franja de luz norte",caption:"Una raja alta al norte. El resto del muro se queda en calma."}],excerpt:"Una casa baja sobre el farall\xf3n. El mar al poniente, el patio al norte, el viento al sur.",lead:"En Matanzas el oc\xe9ano est\xe1 al oeste y el viento sur no pregunta. Quien abre el estar al poniente sin alero, a las cuatro de la tarde no habita: se esconde.",body:["La casa da la espalda al sur —viento, lluvia corta, cero sol— y se abre en dos direcciones que no se pelean: el mar al poniente, con un alero de 2,80 m y una carpinter\xeda de paliller\xeda; el patio al norte, sin alero, para que el invierno entre hasta el fondo del estar.","El predio es un farall\xf3n de 38 metros sobre el Pac\xedfico. No hay relleno. Un muro de contenci\xf3n de hormig\xf3n tabla toma la cota y el volumen se sienta encima, bajo, para no competir con el horizonte. Desde la ruta se ve apenas un techo de cobre.","Madera de pino radiata impregnada, yeso de cal, cobre en cubierta y en los bajantes. Los oficios vinieron de Litueche y de Santa Cruz. El detalle de la ventana oeste se resolvi\xf3 en obra, con el carpintero, midiendo el sol de marzo a las 16:30."],facts:[{label:"L\xe1mina",value:"C-23-11"},{label:"Comuna",value:"Navidad"},{label:"A\xf1o",value:"2023"},{label:"Superficie",value:"280 m\xb2"},{label:"Cota",value:"+38.20"},{label:"Alero poniente",value:"2,80 m"},{label:"Materia",value:"Cal, pino, cobre"},{label:"Estado",value:"Construido"}]},{slug:"bodega-isla-de-maipo",code:"C-24-07",title:"Bodega Isla de Maipo",location:"Isla de Maipo",comuna:"Isla de Maipo",year:2024,category:"Productivo",area:"1.840 m\xb2",cota:"+341.00",status:"Construido",client:"Vi\xf1a de familia",featured:!0,cover:"/images/bodega-maipo.jpg",images:[{src:"/images/bodega-maipo.jpg",alt:"Nave de hormig\xf3n entre hileras de vi\xf1edo en Isla de Maipo",caption:"La nave es paralela a las hileras. El vi\xf1edo no se corta: se contin\xfaa.",wide:!0},{src:"/images/bodega-maipo-int.jpg",alt:"Sala de barricas con lucernario norte",caption:"El lucernario norte lava el piso. La barrica no necesita teatro."},{src:"/images/modelo.jpg",alt:"Maqueta de cart\xf3n de la bodega sobre el talud",caption:"La maqueta de sitio se hizo antes que la planta."}],excerpt:"Una nave larga enterrada en el talud del vi\xf1edo. Masa t\xe9rmica, lucernario norte, cero gesto.",lead:"Una bodega no es un pabell\xf3n de visitas. Es un instrumento de temperatura. El talud del Maipo ya era el muro norte que el vino necesitaba.",body:["El predio es una vi\xf1a de cabernet en Isla de Maipo, con un desnivel de cuatro metros entre la calle y el fondo. Enterramos la nave en ese desnivel: el muro norte es tierra, el sur es hormig\xf3n tabla con una franja de lucernario. La temperatura de las barricas se sostiene sin m\xe1quina la mayor parte del a\xf1o.","El programa es claro: recepci\xf3n de uva al este, fermentaci\xf3n, naves de guarda, un espacio m\xednimo para quien visita. No hay sala de catas con vista panor\xe1mica. Hay una mesa bajo el lucernario y un corte que se entiende.","Estructura de p\xf3rticos de hormig\xf3n. Cubierta invertida con aislamiento y cobre. El permiso de edificaci\xf3n se tramit\xf3 en la DOM de Isla de Maipo en siete meses —el corte ayud\xf3: el volumen no asoma m\xe1s de 4,20 m sobre la cota de la calle."],facts:[{label:"L\xe1mina",value:"C-24-07"},{label:"Comuna",value:"Isla de Maipo"},{label:"A\xf1o",value:"2024"},{label:"Superficie",value:"1.840 m\xb2"},{label:"Cota calle",value:"+341.00"},{label:"Desnivel",value:"4,00 m"},{label:"Uso",value:"Bodega y guarda"},{label:"Estado",value:"Construido"}]},{slug:"casa-patio-nunoa",code:"C-22-04",title:"Casa Patio \xd1u\xf1oa",location:"\xd1u\xf1oa",comuna:"\xd1u\xf1oa",year:2022,category:"Residencial",area:"210 m\xb2",cota:"+572.10",status:"Construido",client:"Privado",featured:!1,cover:"/images/casa-patio.jpg",images:[{src:"/images/casa-patio.jpg",alt:"Casa de un piso alrededor de un patio norte con limonero",caption:"Se conserv\xf3 el jard\xedn de frente. El patio nuevo mira al norte.",wide:!0},{src:"/images/casa-patio-int.jpg",alt:"Corredor de yeso abri\xe9ndose al patio con limonero",caption:"El corredor es el estar de verano. El limonero ya estaba."}],excerpt:"Se derrib\xf3 el chalet de los cincuenta. Se guard\xf3 el jard\xedn de frente y se organiz\xf3 la casa alrededor de un patio norte.",lead:"En \xd1u\xf1oa el predio mide doce por treinta y dos. El chalet de 1954 daba la espalda al norte. La casa nueva da la cara.",body:["El encargo era una casa para una familia de cuatro, con un presupuesto en UF que no admit\xeda gestos. El chalet existente ten\xeda el estar al sur y un patio de servicio al norte. Invertimos el corte: el frente a la calle se queda bajo, con el jard\xedn original; el patio nuevo —con el limonero que ya estaba— concentra el programa.","Ladrillo de la demolici\xf3n reutilizado en el muro de medianero. Yeso de cal. Piso de greda. Una sola agua hacia el patio, para que el agua de invierno riegue el limonero antes de irse al punto de infiltraci\xf3n.","Permiso de edificaci\xf3n en la DOM de \xd1u\xf1oa. Recepci\xf3n final en 2023. La casa se habita con las ventanas del patio abiertas de octubre a abril."],facts:[{label:"L\xe1mina",value:"C-22-04"},{label:"Comuna",value:"\xd1u\xf1oa"},{label:"A\xf1o",value:"2022"},{label:"Superficie",value:"210 m\xb2"},{label:"Predio",value:"12 \xd7 32 m"},{label:"Patio norte",value:"48 m\xb2"},{label:"Materia",value:"Ladrillo, cal, greda"},{label:"Estado",value:"Construido"}]},{slug:"pabellon-san-cristobal",code:"C-21-02",title:"Pabell\xf3n San Crist\xf3bal",location:"Pedro de Valdivia Norte",comuna:"Providencia",year:2021,category:"Cultural",area:"180 m\xb2",cota:"+628.40",status:"Construido",client:"Fundaci\xf3n",featured:!1,cover:"/images/pabellon.jpg",images:[{src:"/images/pabellon.jpg",alt:"Pabell\xf3n de cobre y yeso en una terraza del cerro San Crist\xf3bal",caption:"Cobre de cubierta. El cerro ya era la grader\xeda.",wide:!0},{src:"/images/luz-norte.jpg",alt:"Interior del pabell\xf3n con una raja de luz",caption:"Una sola raja. El resto es muro y eco."}],excerpt:"Un pabell\xf3n de 180 m\xb2 en una terraza del cerro. Cobre, yeso, y el San Crist\xf3bal como grader\xeda.",lead:"La fundaci\xf3n ped\xeda un espacio para dos conferencias al mes y una mesa el resto del tiempo. El cerro ped\xeda no ser tallado de m\xe1s.",body:["El pabell\xf3n se sienta en una terraza ya existente, sin nuevo muro de contenci\xf3n. La cubierta de cobre se pliega una vez, para sacar el agua hacia el norte y dejar una raja de luz sobre la mesa. Los muros son de cal sobre alba\xf1iler\xeda reforzada.","Desde adentro se ve un trozo de ciudad y un trozo de cerro. No se ve todo: ver todo es no ver. El aforo es de cuarenta personas. El resto del mes, el espacio es una sala de trabajo con la puerta abierta al talud."],facts:[{label:"L\xe1mina",value:"C-21-02"},{label:"Comuna",value:"Providencia"},{label:"A\xf1o",value:"2021"},{label:"Superficie",value:"180 m\xb2"},{label:"Cota",value:"+628.40"},{label:"Aforo",value:"40"},{label:"Cubierta",value:"Cobre 0,6 mm"},{label:"Estado",value:"Construido"}]},{slug:"escuela-precordillera",code:"C-23-06",title:"Escuela Precordillera",location:"Pirque",comuna:"Pirque",year:2023,category:"Educativo",area:"2.400 m\xb2",cota:"+703.00",status:"Construido",client:"Fundaci\xf3n educacional",featured:!1,cover:"/images/escuela.jpg",images:[{src:"/images/escuela.jpg",alt:"Pabellones de ladrillo y yeso alrededor de patios en Pirque",caption:"Aulas al norte. Recreo a la sombra. El cerro al fondo.",wide:!0},{src:"/images/casa-patio-int.jpg",alt:"Corredor hacia un patio de la escuela",caption:"El corredor es el clima del recreo. El patio, el del aula."}],excerpt:"Rehabilitaci\xf3n y ampliaci\xf3n de una escuela en Pirque. Se guardaron los pabellones; se corrigi\xf3 el norte.",lead:"La escuela ya estaba. Los pabellones daban al poniente y el recreo se asaba a las dos. El encargo no era un edificio nuevo: era un corte que devolviera la sombra y el norte.",body:["Se conservaron los pabellones de ladrillo y se les sum\xf3 un alero calculado para el 21 de diciembre a las 14:00 en latitud 33,6\xb0 S. Las aulas que miraban al poniente se giraron, en el corte, hacia el norte. El recreo queda a la sombra del pabell\xf3n. Los ni\xf1os no est\xe1n en las fotos: est\xe1n en esa sombra.","Alba\xf1iler\xeda reforzada sobre lo existente, cadenas de hormig\xf3n, NCh433. El permiso se tramit\xf3 con la SEREMI de Educaci\xf3n y la DOM de Pirque. La obra dur\xf3 catorce meses, en vacaciones de invierno y de verano. El oficio de la alba\xf1iler\xeda vino de Buin."],facts:[{label:"L\xe1mina",value:"C-23-06"},{label:"Comuna",value:"Pirque"},{label:"A\xf1o",value:"2023"},{label:"Superficie",value:"2.400 m\xb2"},{label:"Aulas",value:"18"},{label:"Alero norte",value:"1,90 m"},{label:"Norma",value:"NCh433 + OGUC"},{label:"Estado",value:"Construido"}]},{slug:"refugio-conguillio",code:"C-22-09",title:"Refugio Conguill\xedo",location:"Parque Nacional Conguill\xedo",comuna:"Melipeuco",year:2022,category:"Residencial",area:"92 m\xb2",cota:"+1.120.00",status:"Construido",client:"Privado",featured:!1,cover:"/images/refugio.jpg",images:[{src:"/images/refugio.jpg",alt:"Refugio de piedra volc\xe1nica y madera entre araucarias",caption:"Piedra del lugar. La araucaria no se toca.",wide:!0},{src:"/images/materia.jpg",alt:"Detalle de cobre y piedra",caption:"El cobre trabaja a mil cien metros. La piedra, siempre."}],excerpt:"Noventa y dos metros entre araucarias. Piedra volc\xe1nica, lenga y un vano que mira el Llaima.",lead:"El encargo era un refugio para cuatro fines de semana al a\xf1o. El parque ped\xeda no dejar huella de m\xe1s. Noventa y dos metros es el tama\xf1o de esa conversaci\xf3n.",body:["Se levant\xf3 sobre pilotes para no cortar ra\xedces. La piedra es volc\xe1nica, del mismo predio, asentada con mortero de cal. La cubierta es de lenga y cobre. Un solo vano grande mira el Llaima; el resto son rasgaduras para no competir con el bosque.","No hay red. Fotovoltaica, le\xf1a, un pozo. La CONAF revis\xf3 el emplazamiento. La obra se hizo en tres ventanas de verano, con oficios de Melipeuco y de Temuco."],facts:[{label:"L\xe1mina",value:"C-22-09"},{label:"Comuna",value:"Melipeuco"},{label:"A\xf1o",value:"2022"},{label:"Superficie",value:"92 m\xb2"},{label:"Cota",value:"+1.120"},{label:"Sistema",value:"Pilotes, fuera de red"},{label:"Materia",value:"Piedra, lenga, cobre"},{label:"Estado",value:"Construido"}]},{slug:"taller-cota",code:"C-18-01",title:"Taller COTA",location:"Pedro de Valdivia Norte",comuna:"Providencia",year:2018,category:"Estudio",area:"320 m\xb2",cota:"+612.40",status:"Construido",client:"COTA",featured:!1,cover:"/images/taller.jpg",images:[{src:"/images/taller.jpg",alt:"Interior del taller COTA con maquetas sobre mesas de roble",caption:"Mesas de roble. Maquetas de sitio. El norte entra a las 11:00.",wide:!0},{src:"/images/mesa.jpg",alt:"Mesa de dibujo con reglas y un corte",caption:"El corte se dibuja a mano antes que el render."},{src:"/images/modelo.jpg",alt:"Maqueta de cart\xf3n de una casa en talud",caption:"Si la maqueta no se entiende, el edificio tampoco."}],excerpt:"Una casa en el talud de San Crist\xf3bal convertida en taller. Aqu\xed se toman las cotas.",lead:"En 2018 compramos una casa de los setenta en El Cerro. El estar daba al sur. Lo primero que hicimos fue abrir el norte.",body:["El taller es el primer proyecto que nos hicimos a nosotros. Se derrib\xf3 un muro, se abri\xf3 una raja de 8,40 m al norte, y las mesas de roble se alinearon con esa luz. Las maquetas se fotograf\xedan siempre a las 11:00, cuando el sol no miente.","Abajo, archivo y muestras de materia. Arriba, las seis mesas. El patio de atr\xe1s es el talud del cerro, con un array\xe1n que no se toca. Quien viene a encargar un predio se sienta en esa mesa, con el corte delante, no con un flythrough."],facts:[{label:"L\xe1mina",value:"C-18-01"},{label:"Comuna",value:"Providencia"},{label:"A\xf1o",value:"2018"},{label:"Superficie",value:"320 m\xb2"},{label:"Cota",value:"+612.40"},{label:"Mesas",value:"6"},{label:"Uso",value:"Taller y archivo"},{label:"Estado",value:"Construido"}]}],n=["Providencia","Vitacura","Lo Barnechea","\xd1u\xf1oa","La Reina","Pirque","Isla de Maipo","Navidad / costa","Otra / fuera de la RM"]}}]);